125	    @Override
126	    public boolean verifyUserInput() {
127	        // make sure the new trip doesn't overlap any existing trips
128	        if ((mDateChanged || !isEditing()) && Logbook.tripExists(getNewTrip())) {
129	            AlertUtils.showError(getActivity(), R.string.error_trip_date);
130	            return false;
131	        }
132	
133	        // start and end dates are set after the DatePickerFragment is closed
134	        // input properties are set in a onTextChanged listener
135	
136	        // update properties that interact directly with the database
137	        getNewTrip().setAnglers(getSelectedAnglers());
138	        getNewTrip().setCatches(getSelectedCatches());
139	        getNewTrip().setLocations(getSelectedLocations());
140	
141	        return true;
