185	    /**
186	     * Removes the given View objects from their parent.
187	     * @param views The View objects to remove.
188	     */
189	    private void removeViews(ArrayList<View> views) {
190	        for (View view : views) {
191	            ViewGroup parent = ((ViewGroup)view.getParent());
192	            if (parent != null)
193	                parent.removeView(view);
194	        }
