79	    public Trip(JSONObject jsonTrip) throws JSONException {
80	        super(jsonTrip);
81	        init();
82	
83	        mStartDate = new Date(jsonTrip.getLong(Json.START_DATE));
84	        mEndDate = new Date(jsonTrip.getLong(Json.END_DATE));
85	
86	        String notes = jsonTrip.getString(Json.NOTES);
87	        mNotes = notes.isEmpty() ? null : notes;
88	
89	        // anglers
90	        JSONArray jsonAnglers = jsonTrip.getJSONArray(Json.ANGLERS);
91	        mUsedAnglers.setObjects(JsonImporter.parseUserDefineArray(jsonAnglers, new JsonImporter.OnGetObject() {
92	            @Override
93	            public UserDefineObject onGetObject(String name) {
94	                return Logbook.getAngler(UUID.fromString(name));
95	            }
96	        }));
97	
98	        // locations
99	        JSONArray jsonLocations = jsonTrip.getJSONArray(Json.LOCATIONS);
100	        mUsedLocations.setObjects(JsonImporter.parseUserDefineArray(jsonLocations, new JsonImporter.OnGetObject() {
101	            @Override
102	            public UserDefineObject onGetObject(String name) {
103	                return Logbook.getLocation(UUID.fromString(name));
104	            }
105	        }));
106	
107	        // catches
108	        JSONArray jsonCatches = jsonTrip.getJSONArray(Json.CATCHES);
109	        mUsedCatches.setObjects(JsonImporter.parseUserDefineArray(jsonCatches, new JsonImporter.OnGetObject() {
110	            @Override
111	            public UserDefineObject onGetObject(String name) {
112	                return Logbook.getCatch(UUID.fromString(name));
113	            }
114	        }));
115	    }
