225	    /**
226	     * Loops through all the Trip's catches and creates an array of {@link Bait} objects that were
227	     * used. The resulting array has unique values.
228	     *
229	     * @return An array of {@link Bait} objects used during this trip.
230	     */
231	    public ArrayList<UserDefineObject> getBaits() {
232	        ArrayList<UserDefineObject> result = new ArrayList<>();
233	        ArrayList<UserDefineObject> catches = getCatches();
234	
235	        for (UserDefineObject obj : catches) {
236	            Bait bait = ((Catch) obj).getBait();
237	            if (bait == null)
238	                continue;
239	
240	            boolean add = true;
241	
242	            // check to see if the current bait already exists in the result
243	            for (UserDefineObject o : result)
244	                if (o.getIdAsString().equals(bait.getIdAsString())) {
245	                    add = false;
246	                    break;
247	                }
248	
249	            if (add)
250	                result.add(bait);
251	        }
252	
253	        return result;
254	    }
