/**
 * Checks to see if the given {@link Trip} overlaps an existing {@link Trip} in the database.
 *
 * @param trip The {@link Trip} to check.
 * @param excludeSelf True to ignore the {@link Trip} in the database with the same id as the
 *                    given {@link Trip}; false otherwise. This is needed when editing an
 *                    existing {@link Trip}, otherwise the {@link Trip} being edited would
 *                    always overlap itself.
 * @return True if the given {@link Trip} overlaps an existing {@link Trip}; false otherwise.
 */
public static boolean tripExists(Trip trip, boolean excludeSelf) {
    ArrayList<UserDefineObject> trips = getTrips();

    for (UserDefineObject object : trips) {
        // a trip can't overlap itself
        if (excludeSelf && trip.getId() != null && trip.getId().equals(object.getId()))
            continue;

        if (trip.overlapsTrip((Trip)object))
            return true;
    }

    return false;
}

