/**
 * Checks to see if the given {@link Trip} overlaps an existing {@link Trip} in the database.
 *
 * @param trip The {@link Trip} to check.
 * @param excludeId The id of a {@link Trip} to ignore, or null to check against all trips.
 *                  This is needed when editing an existing {@link Trip}; otherwise the
 *                  {@link Trip} being edited would always overlap itself and could never have
 *                  its dates updated.
 * @return True if the given {@link Trip} overlaps an existing {@link Trip}; false otherwise.
 */
public static boolean tripExists(Trip trip, @Nullable UUID excludeId) {
    ArrayList<UserDefineObject> trips = getTrips();

    for (UserDefineObject object : trips) {
        // a trip can't overlap itself
        if (excludeId != null &&
                (excludeId.equals(object.getId()) ||
                        (trip.getId() != null && trip.getId().equals(object.getId()))))
            continue;

        if (trip.overlapsTrip((Trip)object))
            return true;
    }

    return false;
}

